(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.035+t*0.5)*8+Math.cos((y+w1y)*0.025-t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.03-t*0.45)*8+Math.sin((x+w1x)*0.028+t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75+4)*40,0.085,1.8],
    [200+Math.sin(t*0.7+6)*90,30+Math.cos(t*0.5+3)*60,0.095,2.4]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    mS+=Math.sin(d*f*1.3-t*sp*0.4+3.0)*0.5;
  }
  const act=aS/9,inh=iS/9,mod=mS/9;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const voronoi=(x,y)=>{
    let md=1e9,md2=1e9;
    for(let i=0;i<src.length;i++){
      const d=Math.sqrt((x-src[i][0])**2+(y-src[i][1])**2);
      if(d<md){md2=md;md=d}else if(d<md2)md2=d;
    }
    return(md2-md)*0.08;
  };
  const vEdge=voronoi(sx,sy);
  const rd1=act-inh*0.7+bg*0.3+spiral;
  const rd2=mod*0.6+Math.sin(rd1*2.0+t*0.8)*0.4;
  const reaction=Math.tanh((rd1+rd2*0.3)*2.2);
  const cellBoundary=Math.max(0,1-Math.abs(reaction)*3);
  const vBlend=vEdge*cellBoundary*2;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=reaction*0.65+cell*0.15+vBlend*0.2;
  const v=blend*0.5+0.5;
  const pal=[
    [5,10,45],[10,35,85],[12,65,120],[18,110,135],
    [35,155,140],[120,190,110],[210,195,75],
    [230,150,60],[215,100,55],[180,60,70],
    [120,30,75],[60,18,60],[5,10,45]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.08:1.0;
  const glow=vBlend*0.5;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*90)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*120)|0)
  ];
}
